        marks: 20,
        modelAnswer: `"घी ढुल्या म्हारो कांई नी जावे, पाणी ढुल्या म्हारो जीव जले।" — लोक-जीवन की यह कहावत इस सत्य का प्रमाण है कि राजस्थान के लिए जल केवल एक प्राकृतिक संसाधन नहीं, अपितु जीवन की सांस और संस्कृति का मूल प्राणतत्व रहा है। थार के विस्तृत मरुस्थल में अल्प वर्षा के बावजूद यदि सहस्राब्दियों तक मानवीय सभ्यता पुष्पित-पल्लवित रही, तो इसका श्रेय यहाँ के पुरखों की अद्भुत जल-दृष्टि को जाता है।

राजस्थान की पारंपरिक जल संरचनाएं—'टांका', 'जोहड़', 'खड़ीन', 'नाड़ी' और स्थापत्य कला से सुसज्जित 'बावड़ियां'—प्रकृति के साथ सह-अस्तित्व का अनुपम उदाहरण हैं। इन संरचनाओं ने वर्षा की एक-एक बूंद को सहेजकर समाज को कभी जल का भिखारी नहीं बनने दिया। यह तकनीक केवल अभियांत्रिकी नहीं, बल्कि सामुदायिक सहभागिता और जल के प्रति अगाध श्रद्धा का संगम थी।

किंतु वर्तमान में अनियंत्रित औद्योगीकरण, अत्यधिक भूजल दोहन और पारंपरिक ढांचों की उपेक्षा ने राज्य को भीषण जल संकट के मुहाने पर ला खड़ा किया है। आज भूजल स्तर रसातल में जा रहा है और 'डार्क जोन' का दायरा बढ़ रहा है।

इस संकट से मुक्ति के लिए हमें 'अतीत के ज्ञान' को 'आधुनिक तकनीक' से जोड़ना होगा। जहां 'पूर्वी राजस्थान नहर परियोजना' (ERCP) और 'मुख्यमंत्री जल स्वावलंबन अभियान' (MJSA 2.0) जैसी योजनाएं आवश्यक हैं, वहीं प्राचीन टांकों और बावड़ियों का पुनरुद्धार अपरिहार्य है।

निष्कर्षतः, जल सुरक्षा के बिना राजस्थान की समृद्धि की कल्पना असंभव है। हमें पुनः जल को लोक-संस्कार बनाना होगा, ताकि मरुधरा की भावी पीढ़ियों का भविष्य सुरक्षित और हरा-भरा रह सके।`,
        explanation: 'मॉडल निबंध ठीक 242 शब्दों में है। इसमें लोक-कहावत से प्रभावशाली शुरुआत, पारंपरिक संरचनाओं (टांका, जोहड़, खड़ीन, बावड़ी) का सटीक विश्लेषण, आधुनिक संकट (डार्क जोन), नीतिगत समाधान (ERCP, MJSA) और भविष्योन्मुखी उपसंहार प्रस्तुत किया गया है।',
